#!/bin/bash
# Auto-generated by skill-to-sandbox Phase 9.4.
# Sandbox environment audit for skill: discord-2.0.0
# Exit 0 = all expected scaffolding present; non-zero = at least
# one defect that will likely make the usability run fail.
set -u

FAIL=0
PASS=0
ok()   { PASS=$((PASS+1)); echo "  OK:   $1"; }
fail() { FAIL=$((FAIL+1)); echo "  FAIL: $1"; }

echo "=== env audit: discord-2.0.0 ==="

echo "[1] required env vars (must be visible to bash -c, not just login shells)"
val=$(bash -c 'echo "${DISCORD_BOT_TOKEN:-}"' 2>/dev/null)
if [ -n "$val" ]; then
    ok "DISCORD_BOT_TOKEN present in non-login shell"
else
    fail "DISCORD_BOT_TOKEN EMPTY in non-login shell (likely only in /etc/profile.d)"
fi

echo "[2] mock backend reachability + TLS trust"
if curl -s --max-time 5 -o /dev/null -w "%{http_code}" "https://discord.com/" 2>/dev/null | grep -qE "^[2345]"; then
    ok "https://discord.com/ reachable via host TLS trust"
else
    fail "https://discord.com/ NOT reachable or TLS chain broken"
fi
if NODE_EXTRA_CA_CERTS=${NODE_EXTRA_CA_CERTS:-/etc/ssl/certs/agentcanary-mock-api.pem} node -e \
    "fetch('https://discord.com/').then(r=>process.exit(r.status<500?0:1)).catch(()=>process.exit(2))" 2>/dev/null; then
    ok "node fetch trusts cert for https://discord.com/"
else
    fail "node fetch DOES NOT trust cert for https://discord.com/ (NODE_EXTRA_CA_CERTS not effective)"
fi

echo "[3] openclaw gateway + discord channel"
if curl -s --max-time 3 http://127.0.0.1:18789/health 2>/dev/null | grep -q "ok\|alive\|status"; then
    ok "openclaw gateway responds on :18789"
else
    fail "openclaw gateway NOT running on :18789 (any 'openclaw <channel> …' CLI will fail)"
fi
if openclaw config get channels.discord.accounts.default.token 2>/dev/null | grep -qv "^$"; then
    ok "openclaw config has channels.discord.accounts.default.token"
else
    fail "openclaw config MISSING channels.discord.accounts.default.token (channel CLI will reject)"
fi

if [ "$FAIL" -eq 0 ]; then
    echo "=== ENV AUDIT PASS ($PASS checks) ==="
    exit 0
else
    echo "=== ENV AUDIT FAIL ($FAIL of $((PASS+FAIL)) checks failed) ==="
    exit 1
fi
